/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METInventJournalPostingController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METInventJournalPostingController controller = new METInventJournalPostingController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METInventJournalPostingService), methodstr(METInventJournalPostingService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METInventJournalPostingController    controller;

    /// create controller
    controller = METInventJournalPostingController::construct(_args);

    // execute the service class
    controller.startOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

